insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('un-huerto-con-restos-de-cocina','agricultura',array['ambiente']::text[],'Un huerto con restos de cocina','Prueba si algunas hortalizas pueden volver a brotar a partir de restos que normalmente se botan, como la base de la cebolla china, del apio o de la lechuga, y registra cuánto crecen.','Análisis','3 semanas',14,array['Rebrote','Restos de cocina']::text[],array['investigar','crear']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura observacion. medicion. registro de datos. analisis. restos de hortalizas. recipientes con agua. regla y cuaderno.',$a56agr${"id": "un-huerto-con-restos-de-cocina", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Un huerto con restos de cocina", "resumen": "Prueba si algunas hortalizas pueden volver a brotar a partir de restos que normalmente se botan, como la base de la cebolla china, del apio o de la lechuga, y registra cuánto crecen.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 14, "etiquetas": ["Rebrote", "Restos de cocina"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Hay hortalizas que, puestas en agua o en tierra, vuelven a brotar a partir de la base. Se comparte mucho en redes, pero casi nadie registra cuánto tardan, cuánto crecen ni qué tan constante es el resultado.", "Probarlo con datos permite ver qué funciona realmente y qué es solo una moda."], "desarrollar": ["Reúne las bases de tres o cuatro hortalizas, por ejemplo cebolla china, apio y lechuga, y colócalas en agua o en tierra según corresponda. Mantén todas en un lugar con luz y cambia el agua con frecuencia.", "Durante dos o tres semanas mide el crecimiento de los nuevos brotes y anota qué hortalizas lo logran y cuáles no. Concluye qué restos vale la pena probar y qué cuidados necesitan."], "ampliaciones": [{"titulo": "Agua o tierra", "aporta": "compara el rebrote en agua y en tierra."}, {"titulo": "Trasplante", "aporta": "pasa los brotes a una maceta y observa si siguen creciendo."}, {"titulo": "Aporte real", "aporta": "estima cuánto producto adicional te dio."}], "objetivos": ["Preparar los restos.", "Medir el rebrote.", "Comparar hortalizas.", "Concluir con cautela."], "habilidades": ["Observación.", "Medición.", "Registro de datos.", "Análisis."], "herramientas": ["Restos de hortalizas.", "Recipientes con agua.", "Regla y cuaderno."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Cambia el agua con frecuencia y lava bien lo que vayas a consumir.", "No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse."], "otroSector": "El mismo enfoque de reutilizar lo que se desecha sirve para pensar en reaprovechar insumos en cualquier trabajo."}$a56agr$::jsonb,63),
('cuanto-cuesta-producir-tus-propias-hortalizas','agricultura',array['negocios']::text[],'¿Cuánto cuesta producir tus propias hortalizas?','Anota lo que gastas en macetas, tierra, semillas y agua al cultivar hortalizas y compáralo con lo que costaría comprarlas, para saber cuándo vale la pena económicamente un huerto casero.','Análisis','4 semanas',18,array['Costos','Huerto casero']::text[],array['investigar']::text[],'propios',NULL,'economia agronomia administracion ingenieria agroindustrial estadistica educacion nutricion ingenieria industrial registro de costos. calculos basicos. comparacion. pensamiento critico. hoja de calculo. balanza de cocina. cuaderno de registro.',$a57agr${"id": "cuanto-cuesta-producir-tus-propias-hortalizas", "area": "agricultura", "areas2": ["negocios"], "titulo": "¿Cuánto cuesta producir tus propias hortalizas?", "resumen": "Anota lo que gastas en macetas, tierra, semillas y agua al cultivar hortalizas y compáralo con lo que costaría comprarlas, para saber cuándo vale la pena económicamente un huerto casero.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 18, "etiquetas": ["Costos", "Huerto casero"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Agronomía", "Administración", "Ingeniería Agroindustrial", "Estadística", "Educación", "Nutrición", "Ingeniería Industrial"], "problema": ["Se dice que cultivar en casa ahorra dinero, pero no siempre es cierto: macetas, tierra y semillas cuestan, y muchas plantas se pierden. Sin hacer cuentas, es fácil creer que se ahorra o que se gasta de más.", "Calcular los costos y la cosecha permite ver cuándo conviene y cuándo no, y decidir con más claridad."], "desarrollar": ["Elige dos o tres hortalizas y anota todos los gastos de cultivarlas: recipientes, tierra, semillas, abono y una estimación del agua. Registra qué cosechas obtienes y pésalas.", "Compara el costo por kilo producido con el precio de comprar lo mismo en el mercado. Considera qué costos se repiten y cuáles se hacen una sola vez, y concluye qué cultivos resultan más convenientes en tu caso."], "ampliaciones": [{"titulo": "Reutilizar recipientes", "aporta": "calcula cuánto bajan los costos si reutilizas materiales."}, {"titulo": "Varias cosechas", "aporta": "proyecta el costo a lo largo de un año."}, {"titulo": "Valor no económico", "aporta": "describe otros beneficios que no se miden en dinero."}], "objetivos": ["Registrar los gastos.", "Pesar las cosechas.", "Calcular el costo por kilo.", "Comparar con el mercado."], "habilidades": ["Registro de costos.", "Cálculos básicos.", "Comparación.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo.", "Balanza de cocina.", "Cuaderno de registro."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Usa precios de tu zona y aclara que cambian con el tiempo.", "No presentes el resultado como una recomendación financiera."], "otroSector": "El mismo análisis de costo contra beneficio sirve para decidir si conviene producir algo uno mismo o comprarlo."}$a57agr$::jsonb,64),
('tu-tierra-es-buena-pruebas-caseras-antes-de-sembrar','agricultura',array['ambiente']::text[],'¿Tu tierra es buena? Pruebas caseras antes de sembrar','Haz pruebas sencillas de textura, drenaje y retención de agua a una tierra y aprende a leer qué dicen sobre si sirve para sembrar o qué le conviene agregar.','Análisis','3 semanas',16,array['Suelo','Pruebas caseras']::text[],array['investigar','resolver']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion observacion. pruebas simples. interpretacion. registro fotografico. frasco transparente. agua y una pala pequena. camara del celular.',$a58agr${"id": "tu-tierra-es-buena-pruebas-caseras-antes-de-sembrar", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Tu tierra es buena? Pruebas caseras antes de sembrar", "resumen": "Haz pruebas sencillas de textura, drenaje y retención de agua a una tierra y aprende a leer qué dicen sobre si sirve para sembrar o qué le conviene agregar.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 16, "etiquetas": ["Suelo", "Pruebas caseras"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["Antes de sembrar, casi nadie pregunta cómo es su tierra: puede ser muy arenosa, muy arcillosa o muy compacta, y eso cambia cómo se riega y qué crece. Los análisis de laboratorio son útiles pero poco accesibles para quien empieza.", "Unas pruebas caseras permiten tener una idea general del suelo antes de invertir tiempo y semillas."], "desarrollar": ["Toma muestras de tierra de dos o tres lugares, por ejemplo tu jardín, una maceta y tierra comprada. Haz la prueba del frasco con agua para ver las capas que se forman, la prueba de drenaje con un hoyo con agua y la prueba de amasado con la tierra húmeda.", "Registra con fotos y notas lo que observas y compara las muestras. Concluye qué tipo de tierra tiene cada una y qué podrías agregar, como compost o arena, para mejorarla, con cautela ante lo limitado de las pruebas."], "ampliaciones": [{"titulo": "Después de mejorar", "aporta": "repite las pruebas tras agregar compost."}, {"titulo": "Cuánto retiene", "aporta": "mide cuánta agua retiene cada tierra."}, {"titulo": "Guía de interpretación", "aporta": "crea una tabla de qué significa cada resultado."}], "objetivos": ["Tomar muestras.", "Realizar las pruebas.", "Interpretar los resultados.", "Proponer mejoras."], "habilidades": ["Observación.", "Pruebas simples.", "Interpretación.", "Registro fotográfico."], "herramientas": ["Frasco transparente.", "Agua y una pala pequeña.", "Cámara del celular."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No tomes tierra de lugares que puedan estar contaminados, como cerca de carreteras o basurales, y lávate las manos después de manipularla.", "Aclara que son pruebas aproximadas y no reemplazan un análisis de laboratorio."], "otroSector": "El mismo método de diagnóstico simple sirve para evaluar el estado de otros materiales o terrenos antes de decidir qué hacer."}$a58agr$::jsonb,65),
('semillas-cuantas-germinan-de-verdad-y-como-guardarlas','agricultura',array[]::text[],'Semillas: ¿cuántas germinan de verdad y cómo guardarlas?','Prueba qué porcentaje de semillas de distintas edades o marcas germinan, y averigua cómo guardarlas para que duren, así sabes cuáles conviene sembrar y cuáles descartar.','Análisis','4 semanas',18,array['Semillas','Viabilidad']::text[],array['investigar','resolver']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura control de variables. conteo y porcentajes. graficas. redaccion breve. semillas. papel humedo y platos. hoja de calculo.',$a59agr${"id": "semillas-cuantas-germinan-de-verdad-y-como-guardarlas", "area": "agricultura", "areas2": [], "titulo": "Semillas: ¿cuántas germinan de verdad y cómo guardarlas?", "resumen": "Prueba qué porcentaje de semillas de distintas edades o marcas germinan, y averigua cómo guardarlas para que duren, así sabes cuáles conviene sembrar y cuáles descartar.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 18, "etiquetas": ["Semillas", "Viabilidad"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Se compran o se guardan semillas que luego no brotan, y se desperdicia tiempo y espacio. Las semillas viejas o mal guardadas pierden fuerza, pero no siempre se nota hasta sembrarlas.", "Probar su poder de germinación antes de sembrar y aprender a almacenarlas evita pérdidas."], "desarrollar": ["Reúne semillas de un mismo cultivo de distintas edades o marcas, y coloca veinte de cada tipo entre papel húmedo, mantenidas a la misma temperatura. Cuenta cuántas germinan cada día durante una a dos semanas.", "Calcula el porcentaje de germinación de cada lote y compara. Investiga en fuentes confiables cómo guardar semillas, con el lugar, la humedad y los recipientes, y escribe una guía corta con tus resultados."], "ampliaciones": [{"titulo": "Guardado distinto", "aporta": "guarda semillas en lugares distintos y pruébalas después."}, {"titulo": "Costo por plántula", "aporta": "calcula cuánto cuesta cada planta que realmente brota."}, {"titulo": "Etiqueta de semillas", "aporta": "diseña una etiqueta con fecha y método de guardado."}], "objetivos": ["Preparar lotes comparables.", "Contar la germinación.", "Calcular porcentajes.", "Redactar una guía de guardado."], "habilidades": ["Control de variables.", "Conteo y porcentajes.", "Gráficas.", "Redacción breve."], "herramientas": ["Semillas.", "Papel húmedo y platos.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Usa semillas para cultivo y no uses semillas tratadas con químicos para otros fines.", "Lávate las manos después de manipular semillas."], "otroSector": "El mismo método de probar una tasa de éxito antes de invertir sirve para evaluar cualquier insumo o lote de productos."}$a59agr$::jsonb,66),
('diario-de-una-planta-del-brote-a-la-cosecha','agricultura',array['educacion']::text[],'Diario de una planta: del brote a la cosecha','Sigue una planta desde que brota hasta que la cosechas, con fotos, medidas y notas, y convierte ese registro en un cuaderno de datos que cuente cómo crece y qué la afecta.','Análisis','6 semanas',20,array['Registro de crecimiento','Cuaderno de campo']::text[],array['investigar','crear']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura registro sistematico. fotografia de seguimiento. graficas. comunicacion de resultados. camara del celular. regla. hoja de calculo o cuaderno.',$a60agr${"id": "diario-de-una-planta-del-brote-a-la-cosecha", "area": "agricultura", "areas2": ["educacion"], "titulo": "Diario de una planta: del brote a la cosecha", "resumen": "Sigue una planta desde que brota hasta que la cosechas, con fotos, medidas y notas, y convierte ese registro en un cuaderno de datos que cuente cómo crece y qué la afecta.", "tipo": "Análisis", "tiempo": "6 semanas", "horas": 20, "etiquetas": ["Registro de crecimiento", "Cuaderno de campo"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Casi nadie lleva un registro de cómo crece una planta: se mira de vez en cuando y se olvida lo que pasó. Sin datos, es difícil saber cuánto tardó, qué cambios hubo o qué se podría mejorar.", "Un diario ordenado convierte una experiencia en datos que se pueden analizar y compartir."], "desarrollar": ["Elige una planta de crecimiento rápido y define qué vas a registrar: altura, número de hojas, riego, luz y observaciones. Anótalo cada dos o tres días con una foto desde el mismo ángulo.", "Cuando termine el ciclo, organiza los datos en tablas y gráficas, identifica las etapas de crecimiento y escribe un resumen de qué cambios observaste y qué harías distinto. Presenta el diario como un cuaderno con fotos y datos."], "ampliaciones": [{"titulo": "Línea de tiempo", "aporta": "crea una línea de tiempo visual del ciclo de la planta."}, {"titulo": "Comparar dos plantas", "aporta": "sigue dos plantas con cuidados distintos."}, {"titulo": "Versión para niños", "aporta": "adapta el diario como actividad para estudiantes más pequeños."}], "objetivos": ["Definir qué registrar.", "Documentar el crecimiento.", "Organizar y graficar datos.", "Resumir lo aprendido."], "habilidades": ["Registro sistemático.", "Fotografía de seguimiento.", "Gráficas.", "Comunicación de resultados."], "herramientas": ["Cámara del celular.", "Regla.", "Hoja de cálculo o cuaderno."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro.", "Toma las fotos desde el mismo ángulo y sin incluir a otras personas."], "otroSector": "El mismo hábito de registrar con datos y fotos sirve para documentar cualquier proceso o proyecto a lo largo del tiempo."}$a60agr$::jsonb,67),
('alimentos-andinos-poco-conocidos-un-catalogo','agricultura',array['sociedad']::text[],'Alimentos andinos poco conocidos: un catálogo','Reúne información sobre cultivos andinos poco conocidos, como la oca, el tarwi o la kiwicha, y arma un catálogo que diga dónde crecen, cómo se usan y por qué conviene valorarlos.','Guía','3 semanas',20,array['Cultivos andinos','Alimentos locales']::text[],array['crear','investigar']::text[],'publicos',NULL,'antropologia historia agronomia nutricion comunicaciones biologia sociologia diseno grafico investigacion documental. sintesis. diseno de informacion. redaccion. fuentes publicas. un editor de diseno. un mapa sencillo.',$a61agr${"id": "alimentos-andinos-poco-conocidos-un-catalogo", "area": "agricultura", "areas2": ["sociedad"], "titulo": "Alimentos andinos poco conocidos: un catálogo", "resumen": "Reúne información sobre cultivos andinos poco conocidos, como la oca, el tarwi o la kiwicha, y arma un catálogo que diga dónde crecen, cómo se usan y por qué conviene valorarlos.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Cultivos andinos", "Alimentos locales"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Antropología", "Historia", "Agronomía", "Nutrición", "Comunicaciones", "Biología", "Sociología", "Diseño Gráfico"], "problema": ["En los Andes se cultivan alimentos antiguos y diversos que muchas personas del país casi no conocen. Se consumen poco fuera de su zona y, en algunos casos, su cultivo se está reduciendo.", "Un catálogo claro ayuda a dar a conocer estos alimentos y a valorar a quienes los cultivan."], "desarrollar": ["Elige entre ocho y diez cultivos andinos poco conocidos y busca información pública de instituciones agrarias y de investigación sobre dónde crecen y cómo se preparan. Anota también su forma tradicional de uso.", "Elabora una ficha por cultivo con una descripción, su zona de cultivo, sus usos culinarios y un dato curioso, y arma el catálogo con un diseño uniforme. Cita las fuentes y reconoce a las comunidades que los han conservado."], "ampliaciones": [{"titulo": "Recetas", "aporta": "agrega una receta sencilla para cada alimento."}, {"titulo": "Mapa de altitud", "aporta": "muestra a qué altitud crece cada cultivo."}, {"titulo": "Cultivos en peligro", "aporta": "identifica cuáles se cultivan cada vez menos y por qué."}], "objetivos": ["Reunir información confiable.", "Elaborar fichas.", "Diseñar el catálogo.", "Citar fuentes y comunidades."], "habilidades": ["Investigación documental.", "Síntesis.", "Diseño de información.", "Redacción."], "herramientas": ["Fuentes públicas.", "Un editor de diseño.", "Un mapa sencillo."], "lineamientos": ["Documenta saberes tradicionales con permiso y cita siempre a quien te los comparte; no los presentes como propios ni como recetas con fines médicos.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "No atribuyas propiedades de salud a estos alimentos si las fuentes oficiales no las respaldan."], "otroSector": "La misma forma de catalogar productos poco conocidos sirve para presentar cualquier producto local o tradicional."}$a61agr$::jsonb,68),
('el-agua-escondida-en-tu-plato','agricultura',array['ambiente']::text[],'El agua escondida en tu plato','Calcula con cifras públicas cuánta agua hace falta para producir los alimentos de una comida o de un día y compara qué platos requieren más o menos, para entender el agua que no se ve.','Análisis','2 semanas',16,array['Huella hídrica','Alimentos']::text[],array['investigar']::text[],'publicos',NULL,'agronomia ingenieria ambiental geografia estadistica ciencia de datos ingenieria agricola fisica ingenieria de sistemas busqueda de datos. calculos basicos. graficas. interpretacion critica. fuentes publicas. hoja de calculo. graficos.',$a62agr${"id": "el-agua-escondida-en-tu-plato", "area": "agricultura", "areas2": ["ambiente"], "titulo": "El agua escondida en tu plato", "resumen": "Calcula con cifras públicas cuánta agua hace falta para producir los alimentos de una comida o de un día y compara qué platos requieren más o menos, para entender el agua que no se ve.", "tipo": "Análisis", "tiempo": "2 semanas", "horas": 16, "etiquetas": ["Huella hídrica", "Alimentos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Agronomía", "Ingeniería Ambiental", "Geografía", "Estadística", "Ciencia de Datos", "Ingeniería Agrícola", "Física", "Ingeniería de Sistemas"], "problema": ["Producir alimentos usa mucha agua, pero casi nunca se piensa en ella al comer: no sale del caño, está en el riego, en el ganado y en el procesamiento. Los platos no gastan lo mismo, y conocer esas diferencias ayuda a ver el consumo de otra forma.", "Las cifras varían según el lugar y el método de producción, por lo que hay que usarlas como referencias y no como valores exactos."], "desarrollar": ["Busca en fuentes públicas confiables la huella hídrica de entre diez y quince alimentos comunes, anotando la fuente y el año de cada cifra. Elige tres menús sencillos y calcula la cantidad aproximada de agua de cada uno.", "Compara los menús en una gráfica de barras y escribe qué ingredientes pesan más en cada caso. Señala que son promedios mundiales o regionales, no cifras exactas de tu zona, y no concluyas qué se debe comer o dejar de comer."], "ampliaciones": [{"titulo": "Con equivalencias", "aporta": "traduce los litros a algo cotidiano, como botellas o duchas."}, {"titulo": "Un día completo", "aporta": "calcula el agua escondida en todas las comidas de un día."}, {"titulo": "Producción local", "aporta": "busca si hay datos de huella hídrica de cultivos de tu región."}], "objetivos": ["Reunir cifras de fuentes confiables.", "Calcular el agua por menú.", "Visualizar la comparación.", "Explicar los límites de los datos."], "habilidades": ["Búsqueda de datos.", "Cálculos básicos.", "Gráficas.", "Interpretación crítica."], "herramientas": ["Fuentes públicas.", "Hoja de cálculo.", "Gráficos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "No presentes el resultado como un juicio sobre lo que otras personas comen: son referencias para entender, no para reprochar."], "otroSector": "El mismo cálculo de recursos ocultos sirve para estimar la huella de agua o energía de cualquier producto cotidiano."}$a62agr$::jsonb,69),
('abejas-mariposas-y-huertos-observar-a-los-polinizadores','agricultura',array['ambiente','educacion']::text[],'Abejas, mariposas y huertos: observar a los polinizadores','Observa qué insectos visitan las flores de un huerto o jardín a distintas horas, registra cuáles son y cuántos, y averigua qué plantas atraen más polinizadores.','Investigación','4 semanas',18,array['Polinizadores','Observación']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion observacion. conteo sistematico. fotografia. analisis de datos. cuaderno y cronometro. camara del celular. guias de identificacion.',$a63agr${"id": "abejas-mariposas-y-huertos-observar-a-los-polinizadores", "area": "agricultura", "areas2": ["ambiente", "educacion"], "titulo": "Abejas, mariposas y huertos: observar a los polinizadores", "resumen": "Observa qué insectos visitan las flores de un huerto o jardín a distintas horas, registra cuáles son y cuántos, y averigua qué plantas atraen más polinizadores.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 18, "etiquetas": ["Polinizadores", "Observación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["Muchas hortalizas y frutas dependen de insectos que llevan el polen de una flor a otra. Casi nadie los observa con atención, y sin ellos varios cultivos producirían mucho menos.", "Observar y contar visitas permite ver qué plantas los atraen y cuándo, sin dañarlos ni molestarlos."], "desarrollar": ["Elige un espacio con flores, como un huerto, un jardín o un parque, y fija un punto de observación. Durante diez minutos, a tres horas distintas del día, cuenta y anota las visitas de insectos a las flores, tomando fotos desde lejos.", "Identifica los grupos con ayuda de guías confiables, por ejemplo abejas, moscas o mariposas, sin necesidad de llegar a la especie. Resume qué horarios y qué plantas recibieron más visitas y repite en otro día para comparar."], "ampliaciones": [{"titulo": "Plantas atractivas", "aporta": "compara las visitas entre dos tipos de flores."}, {"titulo": "Clima", "aporta": "relaciona las visitas con la temperatura o el viento."}, {"titulo": "Un rincón para polinizadores", "aporta": "propón qué plantar para atraerlos."}], "objetivos": ["Observar sin molestar.", "Registrar visitas.", "Identificar grupos.", "Comparar horarios y plantas."], "habilidades": ["Observación.", "Conteo sistemático.", "Fotografía.", "Análisis de datos."], "herramientas": ["Cuaderno y cronómetro.", "Cámara del celular.", "Guías de identificación."], "lineamientos": ["Observa desde una distancia segura y no captures ni toques a los insectos; evita el contacto si sabes que eres alérgico a las picaduras.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Aclara que son pocas observaciones y que no representan a toda la zona."], "otroSector": "El mismo método de conteo por intervalos sirve para observar cualquier fenómeno repetitivo, como el flujo de personas en un lugar."}$a63agr$::jsonb,70),
('que-significa-organico-natural-o-ecologico-una-guia-de-etiquetas','agricultura',array['sociedad','negocios']::text[],'¿Qué significa «orgánico», «natural» o «ecológico»? Una guía de etiquetas','Investiga qué significan y cómo se regulan en tu país las etiquetas de alimentos como orgánico, natural o ecológico, y arma una guía breve para entender qué garantizan y qué no.','Guía','3 semanas',16,array['Etiquetas','Consumo informado']::text[],array['crear','investigar']::text[],'publicos',NULL,'nutricion ingenieria alimentaria ingenieria ambiental educacion comunicaciones diseno trabajo social administracion lectura de normas. analisis critico. sintesis. diseno de informacion. paginas de autoridades oficiales. camara del celular. un editor de diseno.',$a64agr${"id": "que-significa-organico-natural-o-ecologico-una-guia-de-etiquetas", "area": "agricultura", "areas2": ["sociedad", "negocios"], "titulo": "¿Qué significa «orgánico», «natural» o «ecológico»? Una guía de etiquetas", "resumen": "Investiga qué significan y cómo se regulan en tu país las etiquetas de alimentos como orgánico, natural o ecológico, y arma una guía breve para entender qué garantizan y qué no.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 16, "etiquetas": ["Etiquetas", "Consumo informado"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Ingeniería Ambiental", "Educación", "Comunicaciones", "Diseño", "Trabajo Social", "Administración"], "problema": ["Muchos alimentos llevan palabras que suenan bien, como natural o ecológico, pero no todas significan lo mismo ni están reguladas de la misma forma. Es fácil pagar de más pensando que una etiqueta garantiza algo que no garantiza.", "Una guía clara ayuda a leer las etiquetas con criterio, sin caer en la desconfianza ni en la confianza ciega."], "desarrollar": ["Busca en las páginas de las autoridades del país qué requisitos existen para usar términos como orgánico o ecológico, y qué sellos o certificaciones existen. Separa lo que está regulado de lo que es solo un término de marketing.", "Fotografía entre cinco y diez etiquetas de productos de tu zona sin identificar tiendas ni personas, y explica qué dice cada una y qué no garantiza. Arma una guía de una página con preguntas simples para leer una etiqueta."], "ampliaciones": [{"titulo": "Preguntas para el productor", "aporta": "agrega qué preguntar al comprar directamente."}, {"titulo": "Comparación de sellos", "aporta": "compara dos sellos distintos y qué exigen."}, {"titulo": "Versión infografía", "aporta": "convierte la guía en una infografía."}], "objetivos": ["Investigar la regulación.", "Distinguir regulado y marketing.", "Analizar etiquetas.", "Armar una guía."], "habilidades": ["Lectura de normas.", "Análisis crítico.", "Síntesis.", "Diseño de información."], "herramientas": ["Páginas de autoridades oficiales.", "Cámara del celular.", "Un editor de diseño."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Usa solo fuentes oficiales para lo que dice la norma y aclara que puede cambiar con el tiempo.", "No acuses a marcas ni tiendas: describe lo que dice una etiqueta y lo que no garantiza."], "otroSector": "El mismo ejercicio de leer lo que una etiqueta promete y lo que no, sirve para evaluar cualquier producto con sellos o declaraciones."}$a64agr$::jsonb,71),
('heladas-calor-y-lluvias-como-afectan-a-los-cultivos-de-tu-zona','agricultura',array['ambiente']::text[],'Heladas, calor y lluvias: ¿cómo afectan a los cultivos de tu zona?','Analiza con datos públicos del clima de tu zona cuándo ocurren heladas, calores intensos o lluvias fuertes y relaciónalos con el calendario de los cultivos principales para ver en qué etapas son más peligrosos.','Análisis','4 semanas',24,array['Clima y cultivos','Datos climáticos']::text[],array['investigar']::text[],'publicos',NULL,'agronomia ingenieria ambiental geografia estadistica ciencia de datos ingenieria agricola fisica ingenieria de sistemas analisis de datos. graficas. pensamiento critico. lectura de fuentes agrarias. datos publicos de clima. hoja de calculo. graficos.',$a65agr${"id": "heladas-calor-y-lluvias-como-afectan-a-los-cultivos-de-tu-zona", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Heladas, calor y lluvias: ¿cómo afectan a los cultivos de tu zona?", "resumen": "Analiza con datos públicos del clima de tu zona cuándo ocurren heladas, calores intensos o lluvias fuertes y relaciónalos con el calendario de los cultivos principales para ver en qué etapas son más peligrosos.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Clima y cultivos", "Datos climáticos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Agronomía", "Ingeniería Ambiental", "Geografía", "Estadística", "Ciencia de Datos", "Ingeniería Agrícola", "Física", "Ingeniería de Sistemas"], "problema": ["El clima marca cuándo se siembra y cuándo se cosecha, y un evento fuera de lo esperado puede dañar un cultivo si coincide con una etapa sensible. Muchas veces se conocen las fechas pero casi no se cruzan con los datos.", "Relacionar clima y calendario ayuda a entender cuándo los cultivos corren más riesgo."], "desarrollar": ["Descarga datos públicos de temperatura y lluvia de una estación cercana, de al menos varios años. Cuenta cuántas veces ocurrieron temperaturas muy bajas, muy altas o lluvias intensas en cada mes.", "Elige un cultivo de tu zona e identifica en fuentes agrarias sus etapas más sensibles. Marca en una gráfica en qué meses coinciden esas etapas con eventos extremos y describe con cautela qué riesgos se observan, aclarando que es un análisis sencillo con pocos años de datos."], "ampliaciones": [{"titulo": "Otra estación", "aporta": "compara dos zonas con distinto clima."}, {"titulo": "Tendencias", "aporta": "observa si los eventos se repiten más con los años."}, {"titulo": "Calendario de riesgo", "aporta": "arma un calendario con los meses de mayor riesgo."}], "objetivos": ["Reunir datos climáticos.", "Contar eventos extremos.", "Relacionarlos con el cultivo.", "Comunicar riesgos con cautela."], "habilidades": ["Análisis de datos.", "Gráficas.", "Pensamiento crítico.", "Lectura de fuentes agrarias."], "herramientas": ["Datos públicos de clima.", "Hoja de cálculo.", "Gráficos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "No presentes el análisis como pronóstico ni como recomendación agrícola; no reemplaza el consejo de técnicos.", "Aclara que pocos años de datos no permiten concluir sobre el cambio climático."], "otroSector": "El mismo cruce entre eventos extremos y calendario sirve para analizar riesgos en el transporte, el turismo o cualquier actividad al aire libre."}$a65agr$::jsonb,72),
('un-banco-de-semillas-y-plantines-para-tu-comunidad','agricultura',array['sociedad','ambiente']::text[],'Un banco de semillas y plantines para tu comunidad','Diseña cómo funcionaría un pequeño banco de semillas y plantines donde vecinos o estudiantes intercambian y guardan semillas, con reglas claras, registro y cuidado.','Plan','4 semanas',22,array['Intercambio de semillas','Comunidad']::text[],array['crear']::text[],'ficticios',NULL,'trabajo social sociologia agronomia educacion administracion gestion de proyectos ingenieria ambiental comunicaciones diseno de procesos. organizacion comunitaria. registro de datos. comunicacion. hoja de calculo. un editor de documentos. plantillas de etiquetas.',$a66agr${"id": "un-banco-de-semillas-y-plantines-para-tu-comunidad", "area": "agricultura", "areas2": ["sociedad", "ambiente"], "titulo": "Un banco de semillas y plantines para tu comunidad", "resumen": "Diseña cómo funcionaría un pequeño banco de semillas y plantines donde vecinos o estudiantes intercambian y guardan semillas, con reglas claras, registro y cuidado.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Intercambio de semillas", "Comunidad"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Agronomía", "Educación", "Administración", "Gestión de Proyectos", "Ingeniería Ambiental", "Comunicaciones"], "problema": ["Las semillas y plantines se pueden compartir para ahorrar y conservar variedades locales, pero si no hay reglas, se pierden, se mezclan o se olvida de dónde vienen. Un banco comunitario necesita organización sencilla para durar.", "Pensar el funcionamiento antes de empezar evita problemas y ayuda a que más personas participen."], "desarrollar": ["Imagina un banco para una comunidad de unas treinta personas. Define dónde se guarda, quién lo cuida, qué se acepta y cómo se registra cada semilla con su nombre, fecha y origen.", "Diseña una ficha de registro, unas reglas simples de intercambio y un plan para probar la germinación de los lotes antes de compartirlos. Anticipa tres problemas, como semillas viejas o mezcladas, y cómo resolverlos."], "ampliaciones": [{"titulo": "Etiquetas", "aporta": "diseña una etiqueta clara para cada sobre."}, {"titulo": "Jornada de intercambio", "aporta": "organiza cómo sería un día de intercambio."}, {"titulo": "Registro de variedades", "aporta": "arma un registro con las variedades que llegan."}], "objetivos": ["Definir el funcionamiento.", "Diseñar el registro.", "Establecer reglas.", "Anticipar problemas."], "habilidades": ["Diseño de procesos.", "Organización comunitaria.", "Registro de datos.", "Comunicación."], "herramientas": ["Hoja de cálculo.", "Un editor de documentos.", "Plantillas de etiquetas."], "lineamientos": ["Usa un caso inventado: no incluyas nombres de vecinos ni comunidades reales sin su permiso.", "Documenta saberes tradicionales con permiso y cita siempre a quien te los comparte; no los presentes como propios ni como recetas con fines médicos.", "Aclara que no se deben compartir semillas de especies que no sean permitidas ni que puedan convertirse en plaga en tu zona."], "otroSector": "El mismo sistema de compartir, registrar y cuidar sirve para cualquier biblioteca comunitaria de herramientas, libros o materiales."}$a66agr$::jsonb,73)
